import{_ as i,o as t,c as s,a2 as n}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse('{"title":"Les Normes Éthiques Interplans","description":"","frontmatter":{},"headers":[],"relativePath":"fr/88-跨位面伦理准则.md","filePath":"fr/88-跨位面伦理准则.md","lastUpdated":1789183869000}'),a={name:"fr/88-跨位面伦理准则.md"};function r(o,e,l,u,c,d){return t(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="les-normes-ethiques-interplans" tabindex="-1">Les Normes Éthiques Interplans <a class="header-anchor" href="#les-normes-ethiques-interplans" aria-label="Permalink to &quot;Les Normes Éthiques Interplans&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Élément</th><th>Contenu</th></tr></thead><tbody><tr><td>N° de document</td><td>88</td></tr><tr><td>Module</td><td>Interaction interplans et règles temporelles</td></tr><tr><td>Mots clés</td><td>éthique interplans, autonomie civilisationnelle, non-interférence, respect culturel, diplomatie symbiotique</td></tr></tbody></table><h2 id="i-le-fondement-philosophique-des-normes-ethiques" tabindex="-1">I. Le Fondement Philosophique des Normes Éthiques <a class="header-anchor" href="#i-le-fondement-philosophique-des-normes-ethiques" aria-label="Permalink to &quot;I. Le Fondement Philosophique des Normes Éthiques&quot;">​</a></h2><p>Les Normes Éthiques Interplans sont les normes morales et les codes de conduite que la Civilisation Symbiotique de l&#39;Ancre doit suivre lors des interactions avec les civilisations d&#39;autres plans. Leur fondement philosophique est le principe de « subjectivité civilisationnelle » — chaque civilisation de chaque plan, quel que soit son niveau de développement, sa forme raciale ou son système social, possède une subjectivité inaliénable et un droit au développement autonome. Aucune civilisation étrangère ne peut priver cette subjectivité pour quelque raison que ce soit, ni imposer sa propre volonté à d&#39;autres civilisations.</p><p>L&#39;établissement de ce fondement philosophique s&#39;inscrit dans la continuité du concept central « anti-prédation » de la Civilisation Symbiotique de l&#39;Ancre. La caractéristique essentielle d&#39;une civilisation prédatrice est de ne pas reconnaître la subjectivité des autres civilisations, de traiter les autres civilisations comme des ressources exploitables ou des objets à conquérir. Pour véritablement dépasser les civilisations prédatrices, la Civilisation Symbiotique de l&#39;Ancre doit totalement abandonner cet état d&#39;esprit dans les interactions interplans, en traitant chaque civilisation rencontrée avec égalité, respect et symbiose.</p><p>Le champ d&#39;application des Normes Éthiques Interplans couvre tous les comportements d&#39;interaction interplans, y compris sans s&#39;y limiter : la navigation interplans, la communication interplans, les activités archéologiques, les échanges commerciaux, les échanges culturels, la coopération technique, ainsi que l&#39;intervention humanitaire en cas d&#39;urgence. Toute organisation et tout individu effectuant une interaction interplans doit se conformer à toutes les dispositions des présentes normes.</p><h2 id="ii-les-six-principes-ethiques" tabindex="-1">II. Les Six Principes Éthiques <a class="header-anchor" href="#ii-les-six-principes-ethiques" aria-label="Permalink to &quot;II. Les Six Principes Éthiques&quot;">​</a></h2><p>Les Normes Éthiques Interplans se composent de six principes fondamentaux, formant un système complet de valeurs éthiques :</p><table tabindex="0"><thead><tr><th>Principe</th><th>Contenu central</th><th>Exigences spécifiques</th></tr></thead><tbody><tr><td>Principe d&#39;Autonomie Civilisationnelle</td><td>Respecter le droit au développement autonome de la civilisation du plan cible, ne pas s&#39;immiscer de force dans ses affaires internes</td><td>Ne pas modifier de force le système social, l&#39;idéologie et la voie de développement de la civilisation cible ; ne pas cultiver d&#39;agents ou de régimes fantoches au sein de la civilisation cible</td></tr><tr><td>Principe de Non-Interférence</td><td>Sauf si la civilisation cible fait face à une crise de niveau d&#39;extinction et demande activement de l&#39;aide, aucune interférence substantielle n&#39;est effectuée</td><td>Ne pas s&#39;immiscer dans les conflits internes de la civilisation cible ; ne pas fournir d&#39;armes ou d&#39;aide militaire à une quelconque partie de la civilisation cible ; ne pas manipuler l&#39;opinion publique et les processus politiques de la civilisation cible</td></tr><tr><td>Principe de Respect Culturel</td><td>Respecter les traditions culturelles, les croyances religieuses et les coutumes de la civilisation cible</td><td>Ne pas porter d&#39;évaluations discriminatoires ou de moqueries malveillantes sur la culture de la civilisation cible ; ne pas imposer de force les produits culturels et les valeurs de son propre plan ; ne pas procéder à une assimilation culturelle au nom de la « civilisation »</td></tr><tr><td>Principe d&#39;Égalité et de Bénéfice Mutuel</td><td>Les relations interplans doivent être fondées sur l&#39;égalité, en veillant à ce que les deux parties bénéficient de la relation</td><td>Ne pas utiliser les avantages technologiques pour un commerce inégal ; ne pas piller les ressources de la civilisation cible ; l&#39;exportation technologique doit tenir compte de la capacité d&#39;acceptation et de l&#39;impact social de la civilisation cible</td></tr><tr><td>Principe d&#39;Impact Minimal</td><td>L&#39;interaction interplans doit réduire autant que possible l&#39;impact externe sur la civilisation cible</td><td>Privilégier les méthodes d&#39;interaction à faible contact et à faible interférence ; la portée et l&#39;intensité des activités d&#39;interaction doivent être strictement contrôlées dans les limites nécessaires ; après l&#39;interaction, évaluer et éliminer les impacts résiduels inutiles</td></tr><tr><td>Principe de Responsabilité</td><td>Tous les comportements d&#39;interaction interplans doivent être traçables, surveillables et responsables</td><td>Établir des archives et des journaux d&#39;interaction complets ; créer une institution indépendante de supervision éthique ; enquêter et sanctionner les comportements violant les normes éthiques</td></tr></tbody></table><p>Il existe un lien logique intrinsèque entre les six principes : le Principe d&#39;Autonomie Civilisationnelle est la valeur fondamentale, le Principe de Non-Interférence est l&#39;exigence centrale, le Principe de Respect Culturel est la manifestation au niveau culturel, le Principe d&#39;Égalité et de Bénéfice Mutuel est la garantie au niveau économique, le Principe d&#39;Impact Minimal est la norme au niveau opérationnel et le Principe de Responsabilité est la contrainte au niveau institutionnel. Les six constituent ensemble une boucle éthique complète de « valeur — exigence — manifestation — garantie — norme — contrainte ».</p><h2 id="iii-les-normes-ethiques-pour-differents-scenarios-d-interaction" tabindex="-1">III. Les Normes Éthiques pour Différents Scénarios d&#39;Interaction <a class="header-anchor" href="#iii-les-normes-ethiques-pour-differents-scenarios-d-interaction" aria-label="Permalink to &quot;III. Les Normes Éthiques pour Différents Scénarios d&#39;Interaction&quot;">​</a></h2><h3 id="_3-1-les-normes-ethiques-pour-les-scenarios-archeologiques" tabindex="-1">3.1 Les Normes Éthiques pour les Scénarios Archéologiques <a class="header-anchor" href="#_3-1-les-normes-ethiques-pour-les-scenarios-archeologiques" aria-label="Permalink to &quot;3.1 Les Normes Éthiques pour les Scénarios Archéologiques&quot;">​</a></h3><p>L&#39;archéologie interplans est l&#39;un des scénarios d&#39;interaction les plus courants, et le cœur de ses normes éthiques est la « non-ingérence ». L&#39;équipe archéologique doit strictement suivre le schéma standard Miroir de Réplication + Espace Isolé + Restitution de Connaissances Uniquement, en veillant à ce que le processus archéologique ne soit pas perçu par la civilisation cible. Pour les plans où une civilisation vivante existe encore, le champ de l&#39;archéologie doit être strictement limité aux zones de ruines abandonnées, et aucune forme de balayage ou de réplication des zones habitées de la civilisation vivante n&#39;est autorisée.</p><p>Lorsque les connaissances découvertes par l&#39;archéologie sont restituées et publiées, la sensibilité culturelle de la civilisation cible doit être respectée. Si les découvertes archéologiques impliquent des objets sacrés religieux, des restes ancestraux ou des tabous culturels de la civilisation cible, les informations pertinentes doivent subir un examen de sensibilité culturelle par le Comité d&#39;Éthique Interplans avant publication, et les détails sensibles doivent être floutés si nécessaire.</p><h3 id="_3-2-les-normes-ethiques-pour-les-scenarios-de-communication" tabindex="-1">3.2 Les Normes Éthiques pour les Scénarios de Communication <a class="header-anchor" href="#_3-2-les-normes-ethiques-pour-les-scenarios-de-communication" aria-label="Permalink to &quot;3.2 Les Normes Éthiques pour les Scénarios de Communication&quot;">​</a></h3><p>La communication interplans est un moyen d&#39;échange direct avec la civilisation cible, et le cœur de ses normes éthiques est la « sincérité et le respect ». Le contenu de la communication doit être véridique, sans fournir délibérément de fausses informations ni de propagande trompeuse ; le ton de la communication doit être égal, sans traiter avec condescendance les civilisations à plus faible niveau de développement ; les thèmes de la communication doivent être approuvés par la civilisation cible, sans imposer de force l&#39;idéologie ou les croyances religieuses de son propre plan.</p><p>Lors de l&#39;établissement d&#39;une communication avec une civilisation inconnue pour la première fois, la norme de « contact progressif » doit être suivie : envoyer d&#39;abord des signaux mathématiques et physiques neutres pour confirmer le niveau d&#39;intelligence et la capacité de communication de l&#39;autre partie, puis élargir progressivement la portée de l&#39;échange sur la base de la réponse de l&#39;autre partie ; ne pas envoyer d&#39;informations culturelles ou techniques complexes lors du premier contact.</p><h3 id="_3-3-les-normes-ethiques-pour-les-scenarios-commerciaux" tabindex="-1">3.3 Les Normes Éthiques pour les Scénarios Commerciaux <a class="header-anchor" href="#_3-3-les-normes-ethiques-pour-les-scenarios-commerciaux" aria-label="Permalink to &quot;3.3 Les Normes Éthiques pour les Scénarios Commerciaux&quot;">​</a></h3><p>Le cœur des normes éthiques du commerce interplans est l&#39;« équité et la durabilité ». Le commerce doit être fondé sur le consentement volontaire des deux parties, sans utiliser l&#39;asymétrie d&#39;information ou les avantages technologiques pour des transactions coercitives ; les prix commerciaux doivent être équitables, sans fixation de prix prédatrice ; les marchandises commerciales ne doivent pas inclure de contenus susceptibles de provoquer un choc social ou des dommages écologiques à la civilisation cible.</p><p>Une attention particulière doit être accordée au fait que le commerce interplans de technologies de culture et d&#39;armes à haute énergie est soumis aux restrictions éthiques les plus strictes. Exporter des technologies de culture de haut niveau vers des civilisations à plus faible niveau de développement peut conduire au déséquilibre de leurs structures sociales et à l&#39;intensification de leurs conflits internes ; exporter des armes peut directement déclencher des guerres. Par conséquent, ces deux types de commerce sont interdits en principe, et ne peuvent être menés qu&#39;après approbation par une session plénière de l&#39;Assemblée Délibérante de l&#39;Ancre dans des circonstances extrêmement particulières.</p><h3 id="_3-4-les-normes-ethiques-pour-les-scenarios-d-intervention-d-urgence" tabindex="-1">3.4 Les Normes Éthiques pour les Scénarios d&#39;Intervention d&#39;Urgence <a class="header-anchor" href="#_3-4-les-normes-ethiques-pour-les-scenarios-d-intervention-d-urgence" aria-label="Permalink to &quot;3.4 Les Normes Éthiques pour les Scénarios d&#39;Intervention d&#39;Urgence&quot;">​</a></h3><p>Lorsque la civilisation du plan cible fait face à une crise de niveau d&#39;extinction (telle qu&#39;un impact d&#39;astéroïde, une super-peste, un effondrement des lois), la Civilisation Symbiotique de l&#39;Ancre peut procéder à une intervention humanitaire. Mais même dans de telles situations d&#39;urgence, les normes éthiques suivantes doivent être respectées :</p><ul><li>Avant l&#39;intervention, le consentement éclairé de la civilisation cible doit être obtenu autant que possible ; si la civilisation cible ne peut pas répondre efficacement en raison de la crise, le Comité d&#39;Éthique Interplans porte un jugement de « consentement présumé » en son nom</li><li>Les moyens d&#39;intervention doivent choisir le schéma ayant le moins d&#39;impact sur la civilisation cible, en privilégiant l&#39;intervention indirecte (comme modifier l&#39;orbite de l&#39;astéroïde) plutôt que l&#39;intervention directe (comme une arrivée directe pour le sauvetage)</li><li>Pendant l&#39;intervention, aucune occasion ne peut être saisie pour obtenir les ressources ou la technologie de la civilisation cible</li><li>Après la fin de l&#39;intervention, un retrait immédiat est exigé, sans laisser de présence permanente sur le plan cible</li><li>Ensuite, un rapport d&#39;intervention complet doit être soumis au Comité d&#39;Éthique Interplans pour examen éthique</li></ul><h2 id="iv-supervision-ethique-et-traitement-des-violations" tabindex="-1">IV. Supervision Éthique et Traitement des Violations <a class="header-anchor" href="#iv-supervision-ethique-et-traitement-des-violations" aria-label="Permalink to &quot;IV. Supervision Éthique et Traitement des Violations&quot;">​</a></h2><p>L&#39;Univers Hengyuan a établi le « Comité d&#39;Éthique Interplans » comme institution indépendante de supervision éthique, chargée de formuler et d&#39;interpréter les Normes Éthiques Interplans, d&#39;approuver les projets d&#39;interaction interplans à haut risque, de recevoir les plaintes pour violations éthiques et d&#39;enquêter et de juger les violations. Le comité est composé d&#39;éthiciens, de juristes, de scientifiques et de représentants de civilisations issus de différentes races et de différents parcours professionnels, garantissant la diversité et l&#39;équité des décisions.</p><p>Pour les comportements violant les Normes Éthiques Interplans, selon la gravité des circonstances, les mesures de traitement comprennent : l&#39;avertissement verbal, la réprimande écrite, la suspension des qualifications d&#39;interaction interplans, la révocation des permis de navigation, des amendes, l&#39;emprisonnement et, dans les cas extrêmes, l&#39;« exil interplans » (privation du droit de résider dans les plans principaux de l&#39;Univers Hengyuan). Tous les résultats de traitement des violations éthiques sont enregistrés dans les dossiers éthiques personnels ou organisationnels, conservés de façon permanente.</p><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>Les Normes Éthiques Interplans sont une manifestation concentrée de la hauteur morale de la Civilisation Symbiotique de l&#39;Ancre. Elles ne prescrivent pas seulement « ce qui ne doit pas être fait », mais proclament aussi « ce que l&#39;on doit devenir » — une civilisation véritablement grande n&#39;est pas celle qui a conquis beaucoup d&#39;autres civilisations, mais celle qui a respecté la subjectivité de beaucoup d&#39;autres civilisations. Sur la voie de l&#39;Univers Hengyuan vers la symbiose interstellaire, les Normes Éthiques Interplans seront toujours le phare moral qui guide la direction.</p><h2 id="documents-connexes" tabindex="-1">Documents Connexes <a class="header-anchor" href="#documents-connexes" aria-label="Permalink to &quot;Documents Connexes&quot;">​</a></h2><ul><li>81-位面穿梭规则 (Les Règles de Navigation Interplans)</li><li>87-仅回传知识原则 (Le Principe de Restitution de Connaissances Uniquement)</li><li>04-反掠夺主义核心论纲 (Thèse centrale de l&#39;anti-prédationisme)</li></ul>',30)])])}const h=i(a,[["render",r]]);export{m as __pageData,h as default};
